package com.tripnest.controller;
import com.tripnest.dto.ApiDtos.*; import com.tripnest.entity.BookingStatus; import com.tripnest.repository.*; import com.tripnest.service.*; import jakarta.validation.Valid; import org.springframework.data.domain.PageRequest; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController { final AccommodationService stays; final BookingService bookings; final AccommodationRepository accommodations; final UserRepository users; final BookingRepository bookingRepo; public AdminController(AccommodationService s,BookingService b,AccommodationRepository a,UserRepository u,BookingRepository br){stays=s;bookings=b;accommodations=a;users=u;bookingRepo=br;} @GetMapping("/accommodations") public List<AccommodationView> accommodations(){return stays.adminList();} @PostMapping("/accommodations") public AccommodationView create(@Valid @RequestBody AccommodationRequest x){return stays.create(x);} @PutMapping("/accommodations/{id}") public AccommodationView update(@PathVariable Long id,@Valid @RequestBody AccommodationRequest x){return stays.update(id,x);} @DeleteMapping("/accommodations/{id}") public void delete(@PathVariable Long id){stays.remove(id);} @GetMapping("/bookings") public List<BookingView> allBookings(){return bookings.all();} @PatchMapping("/bookings/{reference}/status") public BookingView status(@PathVariable String reference,@Valid @RequestBody StatusRequest x){return bookings.setStatus(reference,x.status());} @GetMapping("/stats") public Map<String,Object> stats(){Map<String,Object> x=new LinkedHashMap<>();x.put("accommodations",accommodations.count());x.put("users",users.count());x.put("bookings",bookingRepo.count());x.put("confirmedBookings",bookingRepo.countByStatus(BookingStatus.CONFIRMED));x.put("cancelledBookings",bookingRepo.countByStatus(BookingStatus.CANCELLED));x.put("upcomingBookings",bookingRepo.countUpcoming(LocalDate.now()));x.put("revenue",bookingRepo.revenue());List<Map<String,Object>> cities=bookingRepo.topCities(PageRequest.of(0,3)).stream().map(r->Map.of("city",r[0],"bookings",r[1])).toList();x.put("topCities",cities);return x;} }
